        // ─── puntosinteres: description in English ───────────────────
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["Located in the heart of the city, the Museo de Historia Natural de Valparaíso is an oasis of knowledge and wonder. With a collection of more than 100,000 specimens, it explores the rich biodiversity of Chile and the world. From ancient fossils to unique marine species, this museum is a must-visit destination for the curious of all ages. Come and discover the secrets of nature!", 2]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>Located in the heart of the port, the Museo Marítimo Nacional de Valparaíso is an iconic place that will immerse you in the rich naval history of the country. Discover the evolution of the Marina de Chile, admire historical ship models, and explore the lives of the sailors who wrote the country's history. A must-visit destination for lovers of the sea and history!</p>", 3]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Museo Histórico de Placilla is a hidden treasure that will transport you to colonial times. Located in an 18th-century mansion, this museum houses a rich collection of objects and documents that narrate the history of Valparaíso and its surroundings. Discover the daily life of former inhabitants, admire the traditional architecture, and immerse yourself in the collective memory of this unique region. A must-visit destination for history and culture lovers!", 4]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor Barón is one of the 15 historical elevators of Valparaíso and a symbol of the city. Built in 1904, this iron and wood elevator will take you from the port to the Cerro Barón neighborhood, offering you breathtaking views of the city and the sea. Enjoy the ride and discover the essence of Valparaíso!</p>", 5]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Iglesia La Matriz is an icon of the city and one of the oldest and most significant buildings in Valparaíso. Built in 1837, this neoclassical church is an outstanding example of 19th-century religious architecture in Chile. Its imposing facade, its high tower, and its welcoming interior make it a place of great beauty and spirituality. A must-visit destination for lovers of architecture and history!", 6]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Monumento a los Héroes de Iquique is an iconic monument that commemorates the brave action of Chilean sailors during the War of the Pacific. Located in the heart of Valparaíso, this impressive monument pays tribute to the heroes who defended Chile's sovereignty in the Battle of Iquique. Its imposing structure and historical significance make it a place of great importance and national pride. A must-visit destination to remember and honor the heroes of the homeland!", 7]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Arco Británico of Valparaíso is a historical monument that commemorates the friendship and alliance between Chile and the United Kingdom. Built in 1911, this imposing arch is an example of neoclassical architecture and a testimony to the commercial and cultural relationship between both countries. Located in the heart of the port, the Arco Británico is an iconic place that evokes the rich history and international connection of Valparaíso. A must-visit destination to discover the city's cultural heritage!", 8]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The <strong>Escalera Piano</strong> is one of the most photographed and rhythmic urban interventions in Valparaíso. Located on <strong>Cerro Concepción</strong>, specifically on Beethoven Street, this staircase pays a visual tribute to music and the name of the street that hosts it.</p><p><br></p><h3><strong>Music on each step</strong></h3><p>Inaugurated in 2013 as part of a public space recovery initiative, its steps were meticulously painted to simulate the keys of a grand piano. The design plays with perspective: when observed from the base, the staircase looks like a giant keyboard that invites pedestrians to \"compose\" their own path as they climb toward the upper part of the hill.</p><p><br></p><h3><strong>A corner for culture</strong></h3><p>The staircase is not just an aesthetic spot; it has become a natural stage for street musicians and cultural events. Its location connects the city flat to residential neighborhoods full of colorful houses and small artist workshops. It is the ideal place for those looking for an iconic photograph that sums up porteño creativity, away from the most crowded circuits.</p><p><br></p><h3><strong>Recommended experience</strong></h3><p>When you reach the top, take the opportunity to explore the surroundings of Cerro Concepción, an area that preserves a very authentic neighborhood life and offers stunning views of the bay.</p>", 9]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["It must be one of the most sought-after doors in Valparaíso. It is located on Cerro Concepción in the Galvez passage. It can be reached via the Papudo passage or Urriola Street.", 10]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["La abuela aburrida, located on Almirante Montt Street in Cerro Concepción, is one of the few murals that has endured for years in Valparaíso. It is a must-see of the city and local urban art.", 11]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Serrano or Cienfuegos staircase of Valparaíso has become an attraction, not only for its 166 steps, but for its mosaic work.", 12]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Reserva Nacional Lago Peñuelas is a protected area located in the Valparaíso region, Chile. This reserve covers an area of approximately 9,200 hectares and houses a wide variety of ecosystems, including forests, wetlands, and grasslands. Lago Peñuelas is the main attraction of the reserve, offering stunning natural landscapes and opportunities for bird watching, fishing, and hiking. The reserve is also home to various species of flora and fauna, some of which are endangered. The Reserva Nacional Lago Peñuelas is an ideal destination for lovers of nature and the outdoors, offering a unique and enriching experience in contact with the natural beauty of Chile.", 13]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["Historicist architecture, Palacio de los Tribunales, Valparaíso, Cultural heritage, Chilean architecture. The Palacio de los Tribunales de Justicia de Valparaíso is an iconic building located in the heart of the city. Built in the 19th century, it is an outstanding example of historicist architecture, inspired by Italian Renaissance architecture. Its design reflects European influence on Chilean architecture of the time. The facade features a symmetrical composition, with a central body and two side wings. It is clad in stone and features rich ornamentation, with columns, arches, moldings, and balconies. An emblematic example of 19th-century Chilean architecture, it combines historical elements with modern functionality. Its preservation is a testimony to the cultural and heritage wealth of Valparaíso.", 14]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Cuartel General del Cuerpo de Bomberos de Valparaíso is an iconic building located in the heart of the city. Built in 1851, it is one of the first fire stations in Chile and an outstanding example of the neoclassical architecture of the era. The building features an imposing facade with a symmetrical composition and elements such as columns, arches, and pediments. The structure is clad in stone and features rich ornamentation, reflecting the importance of the Cuerpo de Bomberos in the city's history. Throughout its history, the Cuartel General has witnessed important events and played a fundamental role in fighting fires and disasters in Valparaíso. Today, it is a symbol of the city's identity and tradition.", 15]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Edificio de Correos y Telégrafos de Chile, located in Valparaíso, is an outstanding example of 20th-century modern Chilean architecture. Built with reinforced concrete, it presents an innovative and functional aesthetic, inspired by the Bauhaus movement. Its design is characterized by curved lines, circular windows, and a spatial distribution that maximizes natural light. The shape of the building, reminiscent of a ship, is a tribute to the city's maritime tradition. This building is considered one of the best exponents of modern architecture in Valparaíso, and its design has influenced subsequent Chilean architecture.", 16]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Edificio de la Cooperativa Vitalicia in Valparaíso is an outstanding example of modern Chilean architecture. Its innovative and functional design reflects the principles of modern architecture, with clean lines, geometric shapes, and special attention to natural lighting. Built in the second half of the 20th century, the building is a testimony to the architectural evolution of Valparaíso during that period. Its modern style integrates harmoniously with the city's urban environment.</p>", 17]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Biblioteca Santiago Severín is a cultural gem in Valparaíso, Chile. It was founded in 1873 and is the second oldest public library in Chile, after the Biblioteca Nacional. Its current building, located in Plaza Simón Bolívar, is an impressive example of neoclassical and Renaissance architecture, featuring elements such as pilasters, tympanums, and capitals. The library houses an impressive collection of over 82,000 book volumes and 260,000 copies of newspapers and magazines. The library has witnessed important historical and cultural events, such as the signing of the Cultural Institutionality Law in 2000 and the presentation of the Pablo Neruda Ibero-American Poetry Prize in 2007. After suffering damage in the 2010 earthquake, the library was restored and reopened in 2011 with significant improvements to its infrastructure and services.</p>", 18]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Parque Cultural de Valparaíso is an iconic space that combines the city's rich cultural and historical wealth with nature and innovation. Located on Cerro Cárcel, it offers a stunning view of the city and the sea. The park houses several cultural spaces, such as the Museo de Bellas Artes, the Archivo Histórico, and the Biblioteca Municipal. It also features green areas, pedestrian paths, and spaces for cultural events and activities.", 19]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Bar Liberty is an iconic establishment located in the heart of Valparaíso, Chile. With over a century of history, this bar is a testimony to the city's rich cultural and nightlife tradition. Bar Liberty is famous for its wide variety of cocktails and drinks, as well as its lively atmosphere, which attracts visitors and locals alike. It is a must-visit place to experience the porteño night and enjoy a drink in a unique atmosphere full of history. Its architecture and interior decoration are an example of the era in which it was built, with elements like wood, mirrors, and lamps that create a cozy and classic atmosphere.", 20]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>This famous staircase, featuring the lyrics of a song by Calle 13, is located on Urriola Street in Cerro Concepción.</p>", 21]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["A mural depicting a characteristic trade of the hill. Decades ago, milk was delivered by people traveling on donkeys through the hills of Valparaíso. The name of the hill is for the same reason: Cerro Los Lecheros.", 22]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Fisher staircase was painted by ChinoAtonal in 2012 and is a must-see attraction in the city. It connects Urriola Street with the Galvez passage and is located on Cerro Concepción, where you can find shops, crafts, food, and many viewpoints.</p>", 23]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The \"La República\" Statue of Valparaíso is a historical monument that has generated confusion due to its location and name. Originally, the statue was located in Plaza La República, in front of General Holley Street, and represented the Republic sitting on a chair, all in bronze. However, the statue found on Paseo Rubén Darío is actually \"La Industria,\" a work by Mathurin Moreau, a French sculptor. This statue represents a woman sitting on an anvil, with a hammer and a gear in her hands. The real \"La República\" statue was lost for a time, but was recovered by the Policía de Investigaciones de Chile in 2019, after 16 years of searching. Currently, it is undergoing restoration to be returned to its original location.", 24]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The mural \"Vida Oceánica\" by María Martner is a masterpiece by the Chilean artist, located in the heart of Valparaíso. This mural, created in 1994, is an outstanding example of public art and the city's cultural identity. The artwork, measuring over 100 square meters, represents the richness and diversity of marine life, with images of fish, seaweed, and other oceanic elements. The mural is a tribute to Valparaíso's connection with the sea and its importance in the city's history and economy. María Martner, a Chilean artist and muralist, is known for her works that reflect the cultural identity and history of Chile. \"Vida Oceánica\" is one of her most emblematic works and has been declared a National Monument.", 25]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["INSOMNIA Teatro Condell is an iconic cultural space in Valparaíso, Chile. Founded in 2005, it started as a Friday cinema ritual and became a cultural benchmark in the city. In 2011, it moved to the Teatro Condell, a historical space that had been restored. Since then, it offers a variety of activities, such as premieres of Chilean cinema, film forums, workshops, and themed slots. In 2018, the space was enhanced with restoration and adaptation projects. Today, INSOMNIA Teatro Condell is a fully equipped space with a high technical and comfort standard.", 26]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["Playa Las Torpederas is one of the most iconic and popular beaches in Valparaíso, Chile. Located in a quiet and protected bay, this beach offers a relaxing and picturesque setting to enjoy the sun, sea, and sand. The beach features a wide strip of golden sand and crystal-clear waters, ideal for swimming, sunbathing, or simply enjoying the view. In addition, there is a variety of services and activities available, such as restaurants, bars, and kayak or paddleboard rentals. One of the most outstanding features of Playa Las Torpederas is its location in the heart of Valparaíso, making it easily accessible by public transport or on foot. Furthermore, the beach offers an impressive view of the city and the port, making it an ideal place to take photos and enjoy the scenery.", 27]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Faro Punta Ángeles is an iconic lighthouse located in the city of Valparaíso, Chile. Built in 1837, it is one of the oldest lighthouses on the Chilean coast and has witnessed the rich maritime history of the region. Standing at a height of 18 meters, the lighthouse offers breathtaking views of the port of Valparaíso and the city. Its architecture is an example of the naval engineering of the era and has been restored to maintain its originality. The lighthouse is a popular spot for tourists and locals, who gather there to enjoy the sunset and the sea view. The surrounding area also features walking trails and picnic areas, making it ideal for a family visit. In addition to its historical and architectural importance, the Faro Punta Ángeles is also a symbol of Valparaíso's identity. It has been the subject of numerous works of art and has been mentioned in literature and music.", 28]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>Immerse yourself in the elegance of the early 20th century by visiting the Palacio Baburizza, an impressive Art Nouveau mansion that evokes the opulence of the golden age of Valparaíso. Originally the residence of a wealthy Croatian family, today it houses the Museo Municipal de Bellas Artes, where you can admire an outstanding collection of 19th and 20th-century Chilean and European painting. Stroll through its richly decorated halls, let yourself be surprised by its architectural details, and enjoy panoramic views of the port and the bay from its balconies. A walk through its well-manicured gardens complements this experience that will transport you to a past full of charm and sophistication. Discover history and art in a unique setting that captures the vibrant and nostalgic essence of Valparaíso.</p>", 29]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Reloj Turri, an elegant neoclassical style tower, stands as an iconic symbol in Plaza Sotomayor, the historical heart of Valparaíso. Built at the beginning of the 20th century, this monument not only marks time but also testifies to the architectural wealth and splendor of the port's golden age. Its careful structure and strategic location make it an essential meeting point and an excellent place to orient yourself in the city. Admire its detailed design, listen to its chimes, and capture memorable photographs with the backdrop of the port and surrounding historical buildings. A walk through the plaza is not complete without contemplating the majesty of the Reloj Turri, a landmark that evokes the living history of Valparaíso.", 31]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>From the summit of Cerro Barón, the Iglesia San Francisco stands out as the first lookout for sailors. Built in 1845, its brick tower served as a nautical reference, earning it the nickname \"El Faro del Barón.\" Despite the fires, this National Monument symbols porteño resilience and faith in the port. It is an essential neoclassical landmark that dominates the bay's horizon.</p>", 32]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE SINCE 2024*</strong></p><p><br></p><p>The Ascensor Polanco is a unique gem in Valparaíso due to its vertical shaft, unlike the inclined funiculars. Inaugurated in 1915, its access is a cinematic experience: a 150-meter tunnel that goes into the bowels of the hill to take you to an elevator that emerges in a Neo-Gothic tower. With its elevated skywalk, it offers a 360-degree view of the porteño amphitheater, standing as a bold testimony to early 20th-century engineering.</p>", 33]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>Inaugurated in 1902, the Ascensor Reina Victoria is the gateway to the mystical Cerro Alegre. It stands out for its steep incline and its wooden cars that seem to defy gravity. Upon arriving, visitors are greeted by colorful urban art and architecture influenced by British and German styles. It is an icon of the port's golden era, connecting the busy city flat with the bohemian elegance of one of Valparaíso's most photogenic neighborhoods.</p>", 34]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>Dominating Cerro Concepción, the Iglesia Luterana is a symbol of religious freedom in Chile. Built in 1897 by the German community, its Neo-Gothic architecture and its distinctive red roof break the porteño horizon. It was the first Protestant temple to feature a tower and bells, defying the restrictions of the era. Today, its silhouette is an essential part of the landscape protected by UNESCO and a testimony to the port's cultural diversity.</p>", 35]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["Located in the heart of Cerro Alegre, the mural \"Día Uno\" is a work by the renowned artist Mon Laferte. Inaugurated in 2021, it visually relates the cycle of life and the creative process. Its naive style and vibrant colors contrast with the neighborhood's historical architecture, consolidating Valparaíso as a world capital of urban art. This piece has become a new landmark of cultural pilgrimage, uniting music and painting on the port's walls.", 36]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Iglesia San Luis Gonzaga, located in the heart of Cerro Alegre, has been a pillar of neighborhood identity since the late 19th century. Its neoclassical design, with sober and elegant lines, stands out for its imposing tower that can be seen from various points of the port. Built to serve the growing community of the sector, it has resisted the tests of time and earthquakes, consolidating itself as a spiritual and architectural landmark that dialogues harmoniously with the heritage mansions surrounding it.", 37]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["Located in the El Almendral neighborhood, the Iglesia del Corazón de María is a stronghold of porteño faith. Inaugurated at the end of the 19th century, it stands out for its imposing dome and its Neo-Romanesque architecture that shelters the Virgen del Corazón de María, whose image survived the devastating 1906 earthquake. It is a center of popular devotion that has resisted fires and earthquakes, remaining as a beacon of hope and resilience in one of the city flat's most vibrant areas.", 38]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Parroquia Sagrado Corazón de Jesús, located on Cerro Barón, has been an emblem of porteño faith since its foundation at the beginning of the 20th century. Its French Gothic architecture stands out for its stained glass windows and a tower that rises like a spiritual lighthouse over the bay. This temple is not only a refuge of peace but also a community meeting point that has witnessed the social evolution of the hill, consolidating itself as a heritage landmark that beautifuls the silhouette of Valparaíso.", 39]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Iglesia de la Medalla Milagrosa, in the dynamic Barrio Almendral, is a Neo-Gothic treasure that stands out for its verticality and elegance. Its structure, characterized by pointed arches and an atmosphere of recollection, has been for decades a spiritual refuge from the bustle of the city flat. Although less imposing in size than other parishes, its heritage and devotional value make it a fundamental landmark that tells the religious history and urban development of Valparaíso.", 40]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["Located on Cerro Cordillera, the Mirador Purcell is one of the most authentic balconies looking toward the city's origins. From this point, your gaze locks onto the heart of Barrio Puerto, spotlighting the dome of the Iglesia La Matriz amidst the labyrinth of old rooftops. It is the ideal place to observe the porteño duality: the stillness of historical buildings contrasted with the incessant movement of cranes and containers at the maritime terminal—the living soul of Valparaíso.", 41]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Mirador Ongolmo, located on the winding Avenida Baquedano along Cerro Mariposas, offers one of the widest and most dizzying perspectives of the bay. From this natural balcony, the city unfolds like an infinite amphitheater, where the hills seem to cascade down toward the sea. It is a privileged spot to contemplate the marine horizon and the silhouette of ships, capturing the residential essence and geographical magnitude that defines the untamed character of Valparaíso.", 42]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Cinzano, founded in 1896 in front of Plaza Aníbal Pinto, is the epicenter of traditional porteño bohemian life. Generations of poets, sailors, and artists have passed by its wooden tables, drawn by the nostalgia of its live tangos and boleros. This legendary spot is not just a restaurant but a living museum of Valparaíso's identity, where the aroma of chorrillana and the sound of the piano evoke the port's glory years. It's a must-stop to feel the soul of the city.", 43]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The J. Cruz M. is a hidden legend in the heart of Valparaíso, famous for being the birthplace of the chorrillana. More than a restaurant, it is a cabinet of curiosities where the walls, packed with antiques and memories, tell the sentimental history of the port. Located in a narrow alley, its shared, bohemian atmosphere invites you to dive into popular porteño culture. It's a corner where time stands still amidst old-time music and the area's most iconic flavor.", 44]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>With over 80 years of history, the Restaurante La Españita is a pillar of traditional gastronomy in the El Almendral neighborhood. This iconic spot on Avenida Francia has fed generations of porteños with its home-style cooking and its renowned pastry shop. It is a shelter of flavor and nostalgia that resists the passage of time, keeping alive the essence of the Valparaíso of yesteryear. Its family atmosphere and inherited recipes make it a living stronghold of the port's culinary heritage.</p>", 45]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Sala Rivoli, located in the traditional El Almendral neighborhood, is a space that breathes the nostalgia of old porteño cinema. After years of silence, this building has re-emerged as a vibrant cultural center and performance hall, bringing artistic life back to Victoria Street. With its imposing restored architecture, the Rivoli today hosts film, theater, and live music, consolidating itself as a beacon of cultured bohemian life and an essential meeting point for the revitalization of the Valparaíso city flat.", 46]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Casa Crucero, located in the heart of Cerro Alegre, is a gem of porteño architecture that stands out for its unique shape inspired by the lines of a ship. Built to adapt to the hill's rebellious geography, this heritage mansion evokes Valparaíso's close relationship with the sea. With its large windows that look like portholes and its stepped structure, it represents the ingenuity of architects who defied the slope to create homes with a nautical soul.</p>", 47]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Paseo 21 de Mayo, situated at the top of Cerro Artillería, is the most iconic viewpoint in Valparaíso. Inaugurated at the end of the 19th century, it offers a breathtaking panoramic view of the port and the bay. Guarded by the imposing Museo Marítimo Nacional, its terrace is the place where naval history merges with the daily hustle and bustle of ships. Its craft stalls and historical setting make it a privileged balcony to contemplate the untamed spirit of the \"Jewel of the Pacific.\"</p>", 48]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Parque Merced, located on the hill of the same name, is a symbol of resilience and urban renewal. This space emerged as a green lung after the great fire of 2014, transforming into a place for community gathering and recreation. With its trails, playgrounds, and amphitheater, it offers a privileged view of the neighboring hills and the bay, rescuing neighborhood identity and providing a natural setting that strengthens the social fabric of deep Valparaíso.", 49]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Mirador El Vergel, located on Cerro La Cruz, is a place loaded with porteño mystique. From this balcony, you get one of the most iconic views of the port, highlighting the famous emblem of Santiago Wanderers, a symbol of the unconditional passion for the Dean of Chilean football. It's a spot that merges sports identity with the immensity of the bay, letting you appreciate the daily life of the hills and the maritime movement in a deeply authentic and neighborhood setting.", 50]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Catedral de Valparaíso, situated in front of Plaza Victoria in the El Almendral neighborhood, is the port's main Catholic temple. Its construction, which spanned decades until 1950, features Neo-Gothic architecture with vaulted arches and beautiful rose windows that filter the marine light. After resisting various earthquakes, this National Monument remains as a spiritual pillar and an unmistakable architectural landmark, safeguarding the history and faith of the porteño diocese in its crypt.</p>", 51]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Acantilados Federico Santa María, at the southern end of Playa Ancha, are the most imposing natural balcony of the central coastline. These dizzying walls of rock drop straight into the Pacific, offering a wild landscape where the wind and crashing waves dominate the senses. It is a site of enormous geological value and a sanctuary for local birdlife, allowing visitors to connect with the untamed force of the sea, far from the urban bustle of the main port.", 52]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>Muelle Prat is the historical window and vibrant pulse of Valparaíso. Situated in front of Plaza Sotomayor, this waterfront promenade lets you observe closely the movement of large ships and the port tasks that gave life to the city. It is the starting point for traditional tour boats, where old wooden boats invite you to tour the bay. Between the scent of saltpeter and the cry of seagulls, the pier offers the purest connection between the porteño and their sea.</p>", 53]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Paseo Dimalow, in the heart of Cerro Alegre, is one of the most magical and bohemian corners of Valparaíso. Connected by the historical Ascensor Reina Victoria, this pedestrian promenade stands out for its colorful urban art murals and its architecture that mixes European influences with porteño ingenuity. Its terraces offer a privileged view of Cerro Concepción and the bay, creating a unique atmosphere where heritage history merges with the port's vibrant cultural and gastronomic life.", 54]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Paseo Wheelwright lines the coast of Valparaíso with a direct view of the sea and an ideal environment for walking, cycling, or relaxing in front of the ocean; it can be easily accessed through Muelle Barón or Caleta Portales, and it features benches, a bike path, viewpoints, and children's playgrounds, making it a perfect space to enjoy with the family and contemplate the porteño landscape.</p>", 55]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["The Salto del Agua, located in the locality of Placilla de Peñuelas, is one of the most impressive and unknown natural gems of the Valparaíso commune. It is a spectacular waterfall of approximately 100 meters high, framed by rock cliffs and dense vegetation of native sclerophyllous forest. This site stands out not only for its scenic beauty and hiking potential but also for its historical value, being part of the basin that supplied water to the port at the beginning of the 20th century. It is a sanctuary of biodiversity that invites total disconnection, offering a rural and wild perspective just a few minutes from the urban center.", 56]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor San Agustín, located on Cerro Cordillera, is one of the most unique funiculars in Valparaíso due to its particular route that passes through the interior of a building. Inaugurated in 1913, this elevator connects the busy José Tomás Ramos Street with the upper part of the hill, facilitating access to a residential area loaded with history. Its lower station is harmoniously integrated into the facade of a building, making it a testimony to the porteño architectural ingenuity to optimize space in the city's intricate geography.</p>", 57]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor Cordillera, inaugurated in 1886, is the second oldest elevator in Valparaíso and one of the most iconic in the foundational sector. It connects Serrano Street, in the city flat, with Cerro Cordillera, landing in the picturesque Plaza Eleuterio Ramírez. It is known for being one of the steepest and for offering an immediate transition from the port's commercial bustle to the peaceful residential life of the hills, maintaining its wooden cars that evoke the golden era of porteño railway engineering.</p>", 58]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor Espíritu Santo, inaugurated in 1911, is the preferred access route to the heart of Cerro Bellavista. It connects Aldunate Street, in the city flat (behind Plaza Victoria), with Rudolph Street at the top. This funicular is especially valued by tourists and art lovers, as its upper station leads directly to the start of the Museo a Cielo Abierto, allowing a downhill route among murals by prominent Chilean and Latin American artists.</p>", 59]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The <strong>Plaza Mena</strong>, located in the heart of <strong>Cerro Bellavista</strong>, is popularly known as the <strong>\"Plaza de los Poetas\"</strong>. It is a charming and bohemian public space that pays tribute to great figures of Chilean literature such as Pablo Neruda, Vicente Huidobro, and Gabriela Mistral. What makes this corner truly unique is not just its aesthetic value, but its origin: the colorful mosaics decorating its walls, benches, and planters <strong>were created and installed collectively by the hill's own neighbors</strong>, transforming the plaza into a living symbol of self-management, memory, and love for their neighborhood.</p><p><br></p><h3><strong>A Landmark of the Museo a Cielo Abierto</strong></h3><p>This spot is a central node for those touring the <strong>Museo a Cielo Abierto</strong> circuit. The plaza's surroundings are steeped in urban art, artist workshops, and a peaceful atmosphere that invites you to rest. The sculptures of the poets, surrounded by the community's meticulous mosaic work, create a perfect dialogue between high literature and popular porteño expression.</p><p><br></p><h3><strong>Atmosphere and Neighborhood Life</strong></h3><p>Sitting on the benches of Plaza Mena allows you to experience authentic Valparaíso neighborhood life. Amidst colorful houses, cats strolling in the sun, and the distant sound of printmaking and painting workshops, this corner is the exact reflection of how Bellavista has known how to defend its cultural heritage hand in hand with its people.</p>", 60]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>Mural created by the artist Sebastian Varas Mackenzie.</p>", 61]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>Destino Valparaíso is a cultural, artistic, and gastronomic center of over 5,000 m² located in the former Colegio Alemán building, right on Cerro Concepción. The project, led by the Dib family, rehabilitated this historical monument that had been disused since the 1985 earthquake. Its centerpiece is the Museo del Inmigrante, an immersive 1,850 m² experience that uses cutting-edge technology to tell the story of the foreign colonies (Germans, British, Italians, Arabs, among others) that forged the port's identity between 1850 and 1950. The complex also features a theater, craft shops, multicultural gastronomic spaces, and a 360° viewpoint looking toward the city's natural amphitheater.</p>", 62]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor El Peral, inaugurated on December 7, 1901, is one of the most iconic and visited funiculars in Valparaíso. This elevator was a technological milestone in its time, being the first in the city to use a steam engine. Its importance lies in the fact that it connects the administrative center (the \"plan\") with one of the most beautiful residential and tourist sectors: Cerro Alegre. The lower station is located in Plaza de la Justicia, right next to the Comandancia en Jefe de la Armada building and in front of Plaza Sotomayor. As you go up, the 55-meter ride leaves you directly at Paseo Yugoslavo, a spectacular viewpoint that houses the Palacio Baburizza (home of the Museo Municipal de Bellas Artes).</p>", 63]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE SINCE 2024*</strong></p><p><br></p><p>The Ascensor San Juan de Dios is a hidden gem of the city's heritage. Built in 1906, it connects the bustling city flat with the traditional Cerro San Juan de Dios. It stands out for its wooden infrastructure and its route that crosses backyards and borders residential houses, offering a unique look into authentic neighborhood life in Valparaíso away from the usual tourist circuits.</p>", 64]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>Inaugurated in 1911, the Ascensor El Litre is an essential transport hub for the community of Cerro El Litre. This funicular plays a crucial role in the daily life of its neighbors, overcoming the steep slope of the hill to connect them with the commercial services of the city flat. It is a living example of how these century-old structures remain vital for the urban mobility of Valparaíso.</p>", 65]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor Larraín, built in 1909, connects the Almendral neighborhood with Cerro Larraín. It is famous for its steep slope and for arriving at a beautiful upper square that serves as a neighborhood meeting point. Its metallic structure and wooden cars have withstood the passage of time, preserving the classic romantic atmosphere of early 20th-century porteño engineering.</p>", 66]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE*</strong></p><p><br></p><p>The Ascensor Monjas, inaugurated in 1912, links the city flat with Cerro Monjas. It is one of the longest elevators in Valparaíso, and its journey offers a stunning panoramic view of the eastern side of the bay. Its upper station is located in a quiet residential neighborhood that preserves beautiful examples of traditional architecture.</p>", 67]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE*</strong></p><p><br></p><p>The Ascensor Florida, built in 1906, connects Carrera Street with Cerro Florida. It is widely known because its upper station leaves visitors just a few blocks away from \"La Sebastiana,\" the famous house of poet Pablo Neruda. Its route passes through steep slopes and colorful houses, making it a favorite for photography lovers.</p>", 68]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE*</strong></p><p><br></p><p>Inaugurated in 1911, the Ascensor Mariposas takes its name from the hill it serves: Cerro Mariposas. This elevator is an essential part of the landscape of the area and a direct link for its inhabitants. The lower station is neatly tucked away between neighborhood shops, reflecting the seamless integration of these machines into the urban fabric.</p>", 69]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor Cordillera is one of the true pioneers of the port, being the second oldest elevator in the city (inaugurated in 1887). It links the historic Serrano Street with the upper part of Cerro Cordillera, landing in the Eleuterio Ramírez square. It stands out for its impressive engineering and its crucial role in the daily transit of workers.</p>", 71]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>Inaugurated in 1902, the Ascensor Concepción is the absolute pioneer of Valparaíso, being the very first funicular built in the city. It connects the historic Prat Street with the elegant Paseo Gervasoni on Cerro Concepción. Its wooden cars and its historical route make it an unforgettable experience and an obligatory starting point for any heritage tour.</p>", 72]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor Cumming is a modern mechanical elevator located on the hill of the same name. Unlike the historic funiculars, this system was designed to improve accessibility to the cultural and tourist areas surrounding Cerro Cárcel and the Parque Cultural de Valparaíso, offering a quick and efficient connection for visitors and residents.</p>", 73]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor Villaseca, located on Cerro Artillería, was inaugurated in 1913. It is unique due to its parallel design to the famous Ascensor Artillería, built to meet the high demand of the maritime and residential sector of Playa Ancha. After a long period of abandonment, it has been recovered as a key heritage piece for the city's mobility.</p>", 74]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor Artillería, built in 1893, is one of the most popular and spectacular funiculars in the port. It connects the customs square (Plaza Aduana) with the famous Paseo 21 de Mayo on Cerro Artillería. From its wooden cars, passengers can enjoy one of the most classic and wide panoramic views of the maritime terminal and the bay.</p>", 75]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE*</strong></p><p><br></p><p>The Ascensor Santo Domingo, located on the historic hill of the same name, was built in 1910. It connected the foundational area of the port with a neighborhood rich in oral traditions and colonial architecture. Although it is currently waiting for a complete restoration, its infrastructure remains a vital part of the urban identity of Barrio Puerto.</p>", 76]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE*</strong></p><p><br></p><p>The Ascensor Las Cañas, inaugurated in 1925, is one of the latest historical funiculars built in Valparaíso. It connects the Almendral sector with Cerro Las Cañas. It was deeply affected by the great fire of 2014, and the community has actively petitioned for its recovery as it represents a fundamental pillar for the neighborhood's reconstruction and memory.</p>", 77]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The Ascensor Perdices, built in 1932, is the westernmost funicular in Valparaíso, located on Cerro Playa Ancha. It connects the lower sector of the port with the residential areas of the hill. It is highly valued for its singular layout and because it retains much of its original machinery, functioning as a true engineering time capsule.</p>", 78]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Museo de Bellas Artes de Valparaíso is housed inside the magnificent Palacio Baburizza on Cerro Alegre. This museum safeguards one of the most important art collections in Chile, featuring masterpieces by renowned European and national artists. The experience combines the architectural beauty of the Art Nouveau palace with an exceptional cultural journey.</p>", 79]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Museo de Historia Natural de Valparaíso, located in the historic Palacio Lyon, offers a fantastic journey through the biodiversity and environmental heritage of Chile. Its modern exhibitions include fossils, regional fauna, and interactive displays designed for all ages, making it a center of knowledge and scientific conservation in the heart of the city.</p>", 80]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Museo Marítimo Nacional, located at the top of Cerro Artillería, is the guardian of Chile's naval history. Through its rooms, visitors can explore models of historic ships, navigation instruments, and artifacts belonging to the country's greatest naval heroes, all while enjoying a privileged view of the bay from its gardens.</p>", 81]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Casa Mirador de Lukas, situated on Paseo Gervasoni, celebrates the work and legacy of Renzo Pecchenino (\"Lukas\"), the famous caricaturist who captured the essence, humor, and architecture of Valparaíso like no one else. The museum displays his original drawings, temporary exhibitions, and a cozy shop with his most iconic publications.</p>", 82]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>La Sebastiana is one of the three houses owned by the Nobel laureate Pablo Neruda. Located high up on Cerro Florida, this whimsical museum-house offers an intimate look into the poet's life, filled with his eccentric collections of old maps, ships inside bottles, and colorful stained glass, complemented by a breathtaking 360-degree view of the port.</p>", 83]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Museo a Cielo Abierto is a pioneering urban art initiative located on Cerro Bellavista. Inaugurated in 1992, it consists of a series of 20 murals painted directly onto the retaining walls and facades of the hill by prominent Chilean and Latin American artists, creating a vibrant outdoor art gallery that can be explored on foot.</p>", 84]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Museo Organológico de Valparaíso is a fascinating and unique space dedicated to the history and preservation of musical instruments from different eras and cultures around the world. Located in a charming heritage house, it offers guided tours where visitors can listen to the unique sounds of rare and ancient ethnic instruments.</p>", 85]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Museo Histórico de Placilla is a vital cultural space dedicated to preserving the local memory of the Placilla de Peñuelas sector. Its exhibits cover the pre-Hispanic history, the industrial development of the area, and a detailed look into the historic Battle of Placilla (1891), which defined the political future of Chile.</p>", 86]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Sala de Arte Wenteche is an independent gallery and cultural space that promotes contemporary art and local craftsmanship. It serves as an open platform for emerging artists from the Valparaíso region, hosting regular temporary exhibitions, creative workshops, and cultural encounters that enrich the bohemian life of the hills.</p>", 87]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Galería de Arte Bahía Utópica, located in the heart of Cerro Alegre, is a key reference point for contemporary urban art in Valparaíso. This independent gallery represents a diverse group of local and international painters and sculptors, offering a bold and colorful window into the creative avant-garde of the port.</p>", 88]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Centro Cultural Ex Cárcel, today known as the Parque Cultural de Valparaíso, is a remarkable example of urban transformation. This former public prison has been converted into a vibrant, modern cultural complex featuring theaters, exhibition rooms, dance studios, and large green open areas where community life and arts flourish together.</p>", 89]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Teatro Municipal de Valparaíso is the main stage for performing arts in the city flat. Opened in the mid-20th century, this classic theater hosts a rich year-round program including classical concerts, international theater plays, ballet performances, and traditional film festivals, serving as a pillar of regional culture.</p>", 90]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Centro Extensión Duoc UC, housed in the beautifully restored Edificio Cousiño, is a dynamic cultural center. It offers free high-quality activities to the public, such as theater plays, culinary workshops, live music concerts, and cinema cycles, breathing new life into a historic landmark.</p>", 91]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Cinemateca del Pacífico is a dedicated space for the preservation, study, and screening of classic, independent, and documentary cinema. It has become a mandatory meeting point for local film enthusiasts, offering specialized film cycles and forums that encourage critical dialogue around seventh art masterpieces.</p>", 92]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Biblioteca Santiago Severín, founded in 1873, is the second oldest public library in Chile. Its impressive neoclassical building faces Plaza Simón Bolívar and houses a priceless collection of historic books, rare newspapers, and manuscripts that document the cultural, social, and political history of Valparaíso and the nation.</p>", 93]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Casa de la Cultura de Valparaíso is an open community space dedicated to the development of local arts. It hosts regular artistic workshops, neighborhood meetings, small theater productions, and live music, acting as a crucial engine for grassroots cultural identity.</p>", 94]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>Plaza Bismarck</strong> is one of the most unique and lesser-known squares in Valparaíso, located in the Cerro Playa Ancha neighborhood. Named after the famous German chancellor Otto von Bismarck, this plaza reflects the significant German immigration community that settled in the port city during the 19th century. Surrounded by traditional porteño architecture and lush vegetation, it offers a quiet retreat with lovely views over the city and bay. Its distinctive character, away from the main tourist circuits, makes it a genuine discovery for those who venture beyond the classic routes of Cerro Alegre and Cerro Concepción.</p>", 103]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Plaza Sotomayor is the civic and historical heart of Valparaíso. This grand square is surrounded by imposing heritage buildings and features the Monumento a los Héroes de Iquique at its center, acting as the main gateway to the port and Muelle Prat.</p>", 104]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Plaza Aníbal Pinto is a historic and dynamic square connecting the city flat with the paths to Cerro Alegre and Concepción. Famous for its classic Neptune fountain and surrounding traditional buildings, it is a bustling meeting point for artists, student bohemian life, and historic cafes.</p>", 105]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Plaza Victoria is the main green square of the Almendral neighborhood. Adorned with beautiful French bronze statues, historical fountains, and centennial trees, it serves as a traditional family gathering space, surrounded by classic commercial streets, the Cathedral, and ice cream parlors.</p>", 106]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Plaza Bizarro is a cozy urban space deeply integrated into local daily life. It functions as a recreational area for neighbors, featuring children's playgrounds and seating areas that foster community bonding away from the crowded commercial avenues.</p>", 107]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Plaza Echaurren is the oldest square in Valparaíso, located in the heart of Barrio Puerto. It represents the raw, authentic commercial origin of the city, surrounded by historic buildings, traditional popular restaurants, and the iconic La Matriz church.</p>", 108]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Plaza de la Justicia is a stately square between Plaza Sotomayor and the base of Cerro Alegre. Facing the neoclassical Palacio de Tribunales, it is the home of the lower station of the historic Ascensor El Peral, making it a constant transit point for locals and travelers.</p>", 110]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>Muelle Prat is the historic and lively waterfront promenade of Valparaíso. Visitors can watch massive container ships, purchase local naval crafts, and embark on traditional wooden boat tours offering a classic sea-to-land perspective of the city's majestic natural amphitheater.</p>", 111]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Muelle Barón is a restored old industrial pier converted into a modern recreational space on the coastline. It is a premier spot for watersports, offering a long pedestrian pathway ideal for walking, cycling, and enjoying unobstructed sea views.</p>", 112]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Paseo Wheelwright is a beautiful coastal pedestrian and bicycle path stretching along the waterfront, linking Muelle Barón with Caleta Portales. It offers a relaxing route right next to the sea, equipped with viewpoints, workout areas, and direct views of the passing urban metro train lines.</p>", 113]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Playa Las Torpederas is the most historic and popular beach on the western side of the city, in Playa Ancha. Tucked in a protected bay, it is deeply connected to local urban folklore, offering a traditional bathing spot, a beachfront restaurant, and calm waters.</p>", 115]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The Playa Carvallo, along the scenic Altamirano coastal avenue in Playa Ancha, is a small, rocky, and picturesque beach. While not suitable for swimming due to strong waves, it is a highly favored spot for sunbathing, listening to the ocean breeze, and watching dramatic wave crashes.</p>", 116]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE SINCE 2007*</strong></p><p><br></p><p>The <strong>Ascensor Lecheros</strong>, located on the hill of the same name, is one of the funiculars most charged with history, mystique, and nostalgia within the urban fabric of Valparaíso. Inaugurated in <strong>1906</strong>, it is a National Monument that connects the city flat (Eusebio Lillo Street) with the upper part of the hill. Its imposing wooden and iron structure still rises on the hillside as a melancholy reminder of the splendor of early 20th-century industrial engineering.</p>", 117]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE SINCE 2010*</strong></p><p><br></p><p>The <strong>Ascensor Larraín</strong>, located on the hill of the same name, is another historic and emblematic funicular of Valparaíso that guards the urban and working-class memory of the city. Inaugurated in <strong>1909</strong>, it connects the city flat (Eusebio Lillo Street) with <strong>Cerro Larraín</strong>. Declared a <strong>Historical Monument</strong>, it stands out for overcoming a steep slope through a long stretch of tracks that rises above the roofs and backyards of neighboring houses.</p>", 118]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE SINCE 2021*</strong></p><p><br></p><p>The <strong>Ascensor Artillería</strong> is undoubtedly one of the most iconic, photographed, and strategic funiculars in Valparaíso. Inaugurated in <strong>1893</strong>, it directly connects the customs sector with one of the most spectacular viewpoints of the port. Its imposing wooden structure facing the sea is an unmistakable symbol of the porteño postcard. The upper station leaves you directly at <strong>Paseo 21 de Mayo</strong>, offering the most complete panoramic view of the bay.</p>", 119]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE SINCE 2009*</strong></p><p><br></p><p>The <strong>Ascensor Monjas</strong>, located on the hill of the same name, is a Historical Monument that stands out for its imposing height and unique visual trajectory. Inaugurated in <strong>1912</strong>, it connects the city flat (Baquedano Street) with <strong>Cerro Monjas</strong>. What makes this elevator spectacular is its viaduct structure detached from the hillside in its lower section, creating the sensation of floating over the neighborhood rooftops as the car ascends.</p>", 120]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>If you are looking for a different kind of activity during your visit to Valparaíso, <strong>Valparaíso Lucha Libre</strong> offers a show that mixes sports, theater, humor, and local culture into an authentically porteño experience. Through characters inspired by history, urban legends, politics, and life in the hills, each show features matches filled with excitement for the whole family. You do not need to know the rules of pro-wrestling to enjoy it from the very first moment.</p><p><br></p><p><strong>Valparaíso Lucha Libre is not just a wrestling show: it is a way to experience Valparaíso from the ring, among heroes, villains, and characters that reflect the soul of the city.</strong></p>", 121]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE SINCE 2006*</strong></p><p><br></p><p>The <strong>Ascensor Villaseca</strong>, located on <strong>Cerro Playa Ancha</strong>, is one of the most unique and monumental funiculars in Valparaíso. Inaugurated in <strong>1907</strong>, it stands out for being the only elevator in the port that reaches deep into the western residential sector. It crosses a steep ravine via an imposing iron viaduct, giving it one of the longest tracks in the entire elevator system. Declared a <strong>Historical Monument</strong>, visiting its surroundings lets you explore a different Valparaíso: wide streets, Belle Époque mansions, and vibrant university life far from crowded tourist routes.</p>", 122]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OUT OF SERVICE SINCE 2009*</strong></p><p><br></p><p>The <strong>Ascensor Florida</strong>, located on the hill of the same name, stands tall as a silent witness to the golden age of porteño transit. Inaugurated in <strong>1906</strong>, it connects the city flat (Marconi Street, near Avenida Francia) with <strong>Cerro Florida</strong>. Declared a <strong>Historical Monument</strong>, its wooden and brass structure, picturesquely overgrown by the ravine's vegetation, is part of the melancholy landscape that fascinates photographers. Its surroundings connect organically with the <em>Museo a Cielo Abierto</em>, <em>Plaza Mena</em>, and Pablo Neruda's house-museum, <em>La Sebastiana</em>.</p>", 123]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p><strong>*OPERATIONAL*</strong></p><p><br></p><p>The <strong>Ascensor Concepción</strong> is not just a means of transportation — it is the absolute pioneer of porteño identity. Inaugurated in <strong>1883</strong>, it is the <strong>oldest elevator in Valparaíso</strong> and an obligatory stop to understand the engineering, history, and birth of tourism in the city's hills. Its lower station is on Esmeralda Street, and the upper station deposits you directly into the spectacular <strong>Paseo Gervasoni</strong> on Cerro Concepción, with breathtaking views of the bay. Riding it is a unique sensory experience: the nostalgic creaking of its wooden structure transports you instantly to the 19th century.</p>", 124]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The <strong>Ascensor Mariposas</strong>, located on the hill of the same name, is a valuable historic funicular and <strong>Historical Monument</strong> of Valparaíso. Inaugurated in <strong>1904</strong>, it connects the city flat (Barbosa Street, near Avenida Francia) with <strong>Cerro Mariposas</strong>. Its name comes from the masses of vibrantly colored butterflies that once populated the ravines of the sector. Currently out of service, visiting its surroundings offers the perfect opportunity to step off the usual tourist tracks and connect seamlessly with the upper parts of Cerro Florida and Cerro Bellavista.</p>", 125]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>A museum dedicated to the promotion, dissemination, and research of comic arts and puppetry. In this space, you can discover the tradition of puppets, their techniques, and origins, and see up close marionettes reaching up to 4 meters high. You will also learn about comic arts through the clown, masks, the history of Chilean circus, and world references of comedy.</p><p>Play and interaction are essential here — you can handle puppets on display and dress up in clown attire. Puppet and clown shows are held in our theater room every Sunday.</p>", 126]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>The <strong>Institutional Museum of the Universidad Técnica Federico Santa María (UTFSM)</strong>, located on Cerro Placeres, is dedicated to preserving the history of one of Chile's most prestigious engineering universities. Situated inside an architectural complex declared a <strong>Historical Monument</strong> — often compared to a castle or Hogwarts facing the sea — it honors the memory of <strong>Federico Santa María Carrera</strong>, the philanthropist who bequeathed his fortune to create a world-class technical school. The collection includes historic documents, laboratory instruments, and personal belongings of the founder. A perfect complement to the city's literary and artistic routes.</p>", 127]);
        DB::update("UPDATE puntosinteres SET description = JSON_SET(description, '$.en', ?) WHERE id = ?", ["<p>In the historic heart of Barrio Puerto, where Valparaíso unfolds its magic, our gastronomic concept is born. We are a bridge between two worlds: the mastery of <strong>lomo saltado</strong>, with that authentic smoky touch of Peruvian cuisine, and the excellence of a comforting <strong>paila marina</strong>, prepared with the freshness that only our Chilean coasts can deliver. Come and enjoy cuisine with soul, where every bite tells a story. We look forward to welcoming you to celebrate the best of Chile and Peru at a single table.</p>", 129]);

