        DB::update("UPDATE posts SET titulo = JSON_SET(titulo, '$.en', ?) WHERE id = ?", ["3 Must-Sees on Cerro Bellavista", 1]);
        DB::update("UPDATE posts SET resumen = JSON_SET(resumen, '$.en', ?) WHERE id = ?", ["Cerro Bellavista is poetry with a view of the Pacific. Ride the historic 1911 Espíritu Santo funicular for \$100 and step into an Open-Air Museum with 20 murals painted after the return to democracy. From there, walk between art and viewpoints to La Sebastiana, Pablo Neruda's labyrinthine home with 4 floors full of objects, color and the best panorama of the bay. In one morning you get heritage transport, street art and the Nobel's home: the essence of Valpo on a single hill.", 1]);
        DB::update("UPDATE posts SET titulo = JSON_SET(titulo, '$.en', ?) WHERE id = ?", ["Cerro Polanco, Valparaíso's Vertical and Cultural Secret", 2]);
        DB::update("UPDATE posts SET resumen = JSON_SET(resumen, '$.en', ?) WHERE id = ?", ["To experience the port from its most authentic and community-driven essence, Cerro Polanco is a must-visit destination off the traditional tourist routes. The adventure begins by crossing a mystical 150-meter tunnel carved through rock, then riding its iconic elevator — the only fully vertical one in the city — offering a spectacular panoramic view of the bay. Stepping out into its alleyways, you'll find a vibrant open-air museum of large-scale murals, whose cultural and community heart now beats strongly at Centro Cultural Casa Polanco, a self-managed space that brings together the", 2]);
        DB::update("UPDATE posts SET titulo = JSON_SET(titulo, '$.en', ?) WHERE id = ?", ["The Legend of Emilio Dubois, Valparaíso's \"Criminal Saint\"", 3]);
        DB::update("UPDATE posts SET resumen = JSON_SET(resumen, '$.en', ?) WHERE id = ?", ["The myth of Emilio Dubois: For travelers fascinated by mystery and folklore, learning the story of Emilio Dubois at Cemetery No. 3 in Playa Ancha offers a unique immersion into the port's mysticism. Executed in 1907 for the murder of moneylenders, this Frenchman proclaimed his innocence until the end, winning the sympathy of the people who transformed him from a criminal into a \"Robin Hood\" and folk saint. Today, his shrine is a busy pilgrimage site full of plaques from devotees who give thanks for his favors and claim his soul continues to perform miracles.", 3]);

